const { CompositionStage, useComposition } = window;

const W = 1600, H = 900;
const CREAM = '#F4EFE6';
const SKY = '#4FAFBC';
const INK_DEFAULT = '#23201C';
const HUES = [20, 60, 100, 145, 190, 250, 295, 335];
const ACCENTS = HUES.map(h => `oklch(0.74 0.16 ${h})`);

// --- tandem geometry (side view, rolling right) ---
const R = 160, WY = 640;
const RX = 360, FX = 1250;
const B1 = { x: 620, y: 640 };      // stoker bottom bracket (drives rear wheel)
const B2 = { x: 980, y: 640 };      // captain bottom bracket
const S1 = { x: 566, y: 392 };      // rear seat cluster
const S2 = { x: 926, y: 392 };      // front seat cluster
const HT = { x: 1180, y: 372 }, HB = { x: 1206, y: 452 };
const CR = 75, COG = 25, ARM = 100;
const GROUND = WY + R;
const SCALE = 0.586;                 // bike+riders sized so hat tops meet the tallest hill
const PIVOT_X = 805;
const REVS = 3;                     // wheel revolutions per loop
const CHAIN_P = (2 * Math.PI * CR) / 26;

// external tangents, cog -> stoker chainring
const ux = -(CR - COG) / (B1.x - RX), uy = -Math.sqrt(1 - ux * ux);
const T1 = { x: RX + COG * ux, y: WY + COG * uy };
const T2 = { x: B1.x + CR * ux, y: B1.y + CR * uy };
const Bt1 = { x: RX + COG * ux, y: WY - COG * uy };
const Bt2 = { x: B1.x + CR * ux, y: B1.y - CR * uy };

const TUBES = [
  [RX, WY, B1.x, B1.y], [RX, WY, S1.x, S1.y], [S1.x, S1.y, B1.x, B1.y],
  [S1.x, S1.y, S2.x, S2.y], [B1.x, B1.y, S2.x, S2.y], [S1.x, S1.y, B2.x, B2.y],
  [S2.x, S2.y, B2.x, B2.y], [S2.x, S2.y, HT.x, HT.y], [B2.x, B2.y, HB.x, HB.y],
];

const rnd = (i, s) => {
  const x = Math.sin(i * 127.1 + s * 311.7) * 43758.5453;
  return x - Math.floor(x);
};

function Wheel({ cx, cy, angle, ink, seed }) {
  const spokes = [];
  for (let i = 0; i < 14; i++) {
    const a = (i / 14) * Math.PI * 2;
    spokes.push(
      <line key={i}
        x1={cx + Math.cos(a) * 17} y1={cy + Math.sin(a) * 17}
        x2={cx + Math.cos(a) * (R - 20)} y2={cy + Math.sin(a) * (R - 20)}
        stroke="#9A9385" strokeWidth="3" />
    );
  }
  const dots = [];
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * Math.PI * 2;
    dots.push(
      <circle key={i} r="9" fill={ACCENTS[(i * 3 + seed) % ACCENTS.length]}
        cx={cx + Math.cos(a) * (R - 33)} cy={cy + Math.sin(a) * (R - 33)} />
    );
  }
  return (
    <g>
      <circle cx={cx} cy={cy} r={R - 8} fill="none" stroke={ink} strokeWidth="16" />
      <circle cx={cx} cy={cy} r={R - 22} fill="none" stroke="#BCB4A5" strokeWidth="7" />
      <g transform={`rotate(${angle} ${cx} ${cy})`}>
        {spokes}
        {dots}
        <circle cx={cx} cy={cy} r={16} fill={ink} />
        <circle cx={cx} cy={cy} r={6} fill="#BCB4A5" />
      </g>
    </g>
  );
}

function chainProps(off) {
  return {
    fill: 'none', stroke: '#4A443B', strokeWidth: 9,
    strokeDasharray: `${(CHAIN_P * 0.62).toFixed(3)} ${(CHAIN_P * 0.38).toFixed(3)}`,
    strokeDashoffset: -off,
  };
}

function Chains({ off }) {
  const p = chainProps(off);
  return (
    <g>
      <circle cx={RX} cy={WY} r={COG} {...p} />
      <circle cx={B1.x} cy={B1.y} r={CR} {...p} />
      <line x1={T1.x} y1={T1.y} x2={T2.x} y2={T2.y} {...p} />
      <line x1={Bt1.x} y1={Bt1.y} x2={Bt2.x} y2={Bt2.y} {...p} />
      {/* timing chain: captain -> stoker, equal rings */}
      <circle cx={B2.x} cy={B2.y} r={CR} {...p} />
      <line x1={B1.x} y1={B1.y - CR} x2={B2.x} y2={B2.y - CR} {...p} />
      <line x1={B1.x} y1={B1.y + CR} x2={B2.x} y2={B2.y + CR} {...p} />
    </g>
  );
}

function Pedal({ bb, p, shade, cap }) {
  return (
    <g>
      <line x1={bb.x} y1={bb.y} x2={p.x} y2={p.y} stroke={shade} strokeWidth="15" strokeLinecap="round" />
      <rect x={p.x - 32} y={p.y - 8} width="64" height="16" rx="5" fill={shade} />
      <rect x={p.x - 32} y={p.y - 8} width="64" height="5" rx="2.5" fill={cap} opacity="0.85" />
      <circle cx={p.x} cy={p.y} r={6} fill={CREAM} />
    </g>
  );
}

function Chainring({ bb, angle, ink }) {
  return (
    <g>
      <circle cx={bb.x} cy={bb.y} r={CR - 11} fill={CREAM} stroke={ink} strokeWidth="6" />
      <g transform={`rotate(${angle} ${bb.x} ${bb.y})`}>
        {[0, 1, 2, 3, 4].map(i => (
          <circle key={i} r="15" fill="none" stroke={ink} strokeWidth="5"
            cx={bb.x + Math.cos(i / 5 * Math.PI * 2) * 40}
            cy={bb.y + Math.sin(i / 5 * Math.PI * 2) * 40} />
        ))}
      </g>
    </g>
  );
}

function Speckles() {
  const dots = [];
  for (let i = 0; i < 44; i++) {
    const seg = TUBES[Math.floor(rnd(i, 11) * TUBES.length)];
    const t = 0.12 + rnd(i, 12) * 0.76;
    const dx = seg[2] - seg[0], dy = seg[3] - seg[1];
    const L = Math.hypot(dx, dy) || 1;
    const nx = -dy / L, ny = dx / L;
    const o = (rnd(i, 13) - 0.5) * 8;
    dots.push(
      <circle key={i} r={3 + rnd(i, 14) * 3.4}
        cx={seg[0] + dx * t + nx * o} cy={seg[1] + dy * t + ny * o}
        fill={ACCENTS[Math.floor(rnd(i, 15) * ACCENTS.length)]} />
    );
  }
  return <g>{dots}</g>;
}

function Confetti({ T, total }) {
  const N = 76, life = 3.4, bits = [];
  for (let i = 0; i < N; i++) {
    const ph = ((T / life) + rnd(i, 1)) % 1;
    const t = ph * life;
    const rear = i % 2 === 0;
    const ox = rear ? 230 : 1120;
    const vx = -(110 + rnd(i, 2) * 300), vy = -(230 + rnd(i, 3) * 340);
    const x = ox + rnd(i, 7) * 70 + vx * t;
    const y = 740 + vy * t + 0.5 * 470 * t * t;
    const turns = 2 + Math.floor(rnd(i, 4) * 3);
    const c = ACCENTS[Math.floor(rnd(i, 5) * ACCENTS.length)];
    const s = 10 + rnd(i, 6) * 11;
    const op = Math.min(1, ph * 10) * (1 - ph * ph);
    const shape = rnd(i, 8);
    bits.push(
      <g key={i} transform={`translate(${x} ${y}) rotate(${ph * 360 * turns})`} opacity={op}>
        {shape > 0.72
          ? <circle r={s * 0.46} fill={c} />
          : shape > 0.5
            ? <rect x={-s * 0.5} y={-s * 0.5} width={s} height={s} rx="2" fill={c} transform="rotate(20)" />
            : <rect x={-s * 0.5} y={-s * 0.26} width={s} height={s * 0.52} rx="2" fill={c} />}
      </g>
    );
  }
  const env = Math.max(0, Math.min(1, T / 1.5)) * Math.max(0, Math.min(1, (total - T) / 2.5));
  return <g opacity={env}>{bits}</g>;
}

const IMG = './assets/landscape.png';
const IMG_S = 0.68;
const TILE_W = 2000 * IMG_S;          // 1360
const TILE_H = 1429 * IMG_S;          // 971.7
const IMG_TY = GROUND - 1230 * IMG_S; // road contact aligned to the wheels
const ROAD_TOP = IMG_TY + 1150 * IMG_S;

function Tiles({ off, top }) {
  const p = TILE_W * 2, o = ((off % p) + p) % p;
  const out = [];
  for (let i = -2; i < Math.ceil(W / TILE_W) + 2; i++) {
    const x = i * TILE_W - o;
    const flip = ((i % 2) + 2) % 2 === 1;
    out.push(
      <img key={i} src={IMG} alt="" draggable="false" style={{
        position: 'absolute', left: x + 'px', top: top + 'px',
        width: (TILE_W + 1) + 'px', height: TILE_H + 'px',
        transform: flip ? 'scaleX(-1)' : 'none', transformOrigin: '50% 50%',
      }} />
    );
  }
  return <React.Fragment>{out}</React.Fragment>;
}

function Ground({ dist }) {
  return (
    <React.Fragment>
      <div style={{ position: 'absolute', left: 0, top: 0, width: W + 'px', height: ROAD_TOP + 'px', overflow: 'hidden' }}>
        <Tiles off={dist * 0.5} top={IMG_TY} />
      </div>
      <div style={{ position: 'absolute', left: 0, top: ROAD_TOP + 'px', width: W + 'px', height: (H - ROAD_TOP) + 'px', overflow: 'hidden' }}>
        <Tiles off={dist} top={IMG_TY - ROAD_TOP} />
      </div>
    </React.Fragment>
  );
}

function Saddle({ at, color, ink }) {
  return (
    <g transform={`translate(${at.x - 690} ${at.y - 378})`}>
      <path d="M700,378 L690,352" stroke={ink} strokeWidth="11" strokeLinecap="round" />
      <path d="M642,354 C664,340 702,338 726,348 C732,356 722,364 700,364 L660,366 C646,366 638,360 642,354 Z" fill={color} stroke={ink} strokeWidth="5" strokeLinejoin="round" />
    </g>
  );
}

const X_IN = -1700, X_OUT = 2500;    // fully off-canvas either side (card trails behind)
const CRUISE_X = 330;                // rig centred when the card is in tow
const SCROLL = TILE_W * 4;           // world pan over the whole loop

function knee(H, F, a, b) {
  const dx = F.x - H.x, dy = F.y - H.y;
  const raw = Math.hypot(dx, dy) || 1;
  const ux = dx / raw, uy = dy / raw;
  const d = Math.max(Math.abs(a - b) + 1, Math.min(a + b - 1, raw));
  const x = (d * d + a * a - b * b) / (2 * d);
  const h = Math.sqrt(Math.max(0, a * a - x * x));
  return { x: H.x + ux * x + uy * h, y: H.y + uy * x - ux * h };
}

const THIGH = 170, SHIN = 180;
const HEAD_SAZ = 'data:image/png;base64,';   // front rider (captain)
const HEAD_AIS = 'data:image/png;base64,';   // rear rider (stoker)

function Rider({ hip, sh, head, grip, near, far, ink, img, iw, ih, ox, oy }) {
  const kf = knee(hip, far, THIGH, SHIN);
  const kn = knee(hip, near, THIGH, SHIN);
  const dx = sh.x - hip.x, dy = sh.y - hip.y;
  const L = Math.hypot(dx, dy) || 1;
  const px = -dy / L, py = dx / L;
  const torso = [
    [sh.x + px * 16, sh.y + py * 16], [hip.x + px * 46, hip.y + py * 46],
    [hip.x - px * 46, hip.y - py * 46], [sh.x - px * 16, sh.y - py * 16],
  ].map(p => p[0].toFixed(1) + ',' + p[1].toFixed(1)).join(' ');
  return (
    <g>
      <polyline points={`${hip.x},${hip.y} ${kf.x},${kf.y} ${far.x},${far.y}`}
        fill="none" stroke={ink} strokeWidth="11" strokeLinecap="round" strokeLinejoin="round" opacity="0.55" />
      <line x1={sh.x - 10} y1={sh.y + 10} x2={grip.x - 14} y2={grip.y + 12}
        stroke={ink} strokeWidth="10" strokeLinecap="round" opacity="0.55" />
      <polygon points={torso} fill="#FFFFFF" stroke={ink} strokeWidth="11" strokeLinejoin="round" />
      <line x1={sh.x} y1={sh.y} x2={grip.x} y2={grip.y} stroke={ink} strokeWidth="11" strokeLinecap="round" />
      <polyline points={`${hip.x},${hip.y} ${kn.x},${kn.y} ${near.x},${near.y}`}
        fill="none" stroke={ink} strokeWidth="12" strokeLinecap="round" strokeLinejoin="round" />
      <ellipse cx={near.x} cy={near.y} rx="15" ry="11" fill="none" stroke={ink} strokeWidth="9" />
      <image href={img} xlinkHref={img} x={head.x + ox} y={head.y + oy} width={iw} height={ih} preserveAspectRatio="xMidYMid meet" />
    </g>
  );
}

// --- sky banner towed by a little plane ---
const BANNER_TEXT = 'Turning Thirty in Tandem';
const BAN_L = 900, BAN_H = 96, BAN_A = 13, BAN_LAM = 300;

function wavePath(x0, y0, len, amp, lam, ph, dy) {
  let d = '';
  const steps = 36;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps, x = x0 + len * t;
    const y = y0 + dy + amp * Math.sin((x / lam) * Math.PI * 2 + ph);
    d += (i ? 'L' : 'M') + x.toFixed(1) + ',' + y.toFixed(1) + ' ';
  }
  return d;
}

function SkyBanner({ T, total, X, ink }) {
  const k = T / total;
  const px = X + 470 + 96 + BAN_L / 2;   // plane tows the banner centred over the whole rig
  const py = 62 + Math.sin(T * 0.9) * 10;
  const ph = -T * 2.2;
  const bx = px - BAN_L - 96, by = py + 6;
  const mid = wavePath(bx, by, BAN_L, BAN_A, BAN_LAM, ph, BAN_H / 2);
  const body = wavePath(bx, by, BAN_L, BAN_A, BAN_LAM, ph, 0) +
    'L' + (bx + BAN_L).toFixed(1) + ',' + (by + BAN_H).toFixed(1) + ' ' +
    wavePath(bx, by, BAN_L, BAN_A, BAN_LAM, ph, BAN_H).split('M')[1].split(' ').reverse().join(' ') + ' Z';
  const sparks = [];
  for (let i = 0; i < 84; i++) {
    const sx = bx + 14 + rnd(i, 21) * (BAN_L - 28);
    const sy = by + 8 + rnd(i, 22) * (BAN_H - 16) + BAN_A * Math.sin((sx / BAN_LAM) * Math.PI * 2 + ph);
    const base = 5 + rnd(i, 23) * 9;
    const beat = 0.5 + 0.5 * Math.sin(T * (2.2 + rnd(i, 24) * 4.2) + i * 1.7);
    const tw = 0.55 + 0.45 * beat;
    const r = base * (0.7 + 0.5 * beat);
    const pick = rnd(i, 26);
    const col = pick > 0.66 ? '#C2185B' : pick > 0.33 ? '#E23E8C' : '#B8860B';
    sparks.push(
      <g key={i} transform={`translate(${sx.toFixed(1)} ${sy.toFixed(1)}) rotate(${(rnd(i, 25) * 90 + T * 18 * (rnd(i, 27) > 0.5 ? 1 : -1)).toFixed(1)})`} opacity={tw}>
        <circle r={r * 1.05} fill={col} opacity="0.2" />
        <path d={`M0,${-r} Q${r * 0.16},${-r * 0.16} ${r},0 Q${r * 0.16},${r * 0.16} 0,${r} Q${-r * 0.16},${r * 0.16} ${-r},0 Q${-r * 0.16},${-r * 0.16} 0,${-r} Z`} fill={col} />
        <path d={`M0,${-r * 0.55} Q${r * 0.08},${-r * 0.08} ${r * 0.55},0 Q${r * 0.08},${r * 0.08} 0,${r * 0.55} Q${-r * 0.08},${r * 0.08} ${-r * 0.55},0 Q${-r * 0.08},${-r * 0.08} 0,${-r * 0.55} Z`}
          transform="rotate(45)" fill={col} opacity="0.9" />
      </g>
    );
  }
  const env = Math.max(0, Math.min(1, T / 1.2)) * Math.max(0, Math.min(1, (total - T) / 1.6));
  return (
    <g opacity={env}>
      <defs>
        <clipPath id="banner-clip"><path d={body} /></clipPath>
        <linearGradient id="banner-fill" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#FFF4F8" />
          <stop offset="100%" stopColor="#FBD7E5" />
        </linearGradient>
      </defs>
      <path d={`M${bx + BAN_L},${by + BAN_H / 2} C${bx + BAN_L + 40},${by + BAN_H / 2 - 6} ${px - 70},${py + 34} ${px - 34},${py + 26}`}
        fill="none" stroke={ink} strokeWidth="4" />
      <path d={body} fill="url(#banner-fill)" stroke={ink} strokeWidth="7" strokeLinejoin="round" />
      <g clipPath="url(#banner-clip)">{sparks}</g>
      <path id="banner-mid" d={mid} fill="none" stroke="none" />
      <text fontFamily="'Caveat', cursive" fontSize="88" fontWeight="700" fill={ink} dominantBaseline="middle">
        <textPath href="#banner-mid" xlinkHref="#banner-mid" startOffset="50%" textAnchor="middle">{BANNER_TEXT}</textPath>
      </text>
      <g transform={`translate(${px} ${py})`}>
        <path d="M-78,18 C-46,2 6,-6 44,0 C62,3 70,10 68,16 C66,23 44,32 8,34 C-26,36 -62,30 -78,24 Z"
          fill={ACCENTS[4]} stroke={ink} strokeWidth="7" strokeLinejoin="round" />
        <path d="M-30,6 C-14,-26 -2,-38 8,-36 C16,-34 16,-16 10,6 Z" fill={CREAM} stroke={ink} strokeWidth="6" strokeLinejoin="round" />
        <path d="M-74,16 C-88,-4 -92,-16 -84,-16 C-76,-16 -64,-2 -58,12 Z" fill={ACCENTS[7]} stroke={ink} strokeWidth="6" strokeLinejoin="round" />
        <circle cx="30" cy="12" r="8" fill={CREAM} stroke={ink} strokeWidth="5" />
        <path d="M66,2 L74,30" stroke={ink} strokeWidth="7" strokeLinecap="round" />
      </g>
    </g>
  );
}

// --- towed invitation card on its own pair of wheels ---
// The card raster rides in an HTML layer (an <img>, which the stage serializer
// inlines) while its frame, struts and wheels are drawn in the SVG above it.
const CARD_IMG = 'assets/card.mp4';
const CARD_W = 700, CARD_H = 500, CARD_RW = 46;
const CARD_RIGHT = 416;              // screen-space offset behind the bike

function cardGeo(T, X) {
  const rx = X + CARD_RIGHT, lx = rx - CARD_W;
  const axleY = GROUND - CARD_RW;
  const cardB = axleY - 26;
  return {
    rx, lx, axleY, cardB, cardT: cardB - CARD_H,
    tilt: Math.sin(T * 1.3) * 0.7,
    lift: Math.sin(T * 2.1) * 2,
  };
}

function CardArt({ T, X, zoom }) {
  const g = cardGeo(T, X);
  return (
    <div style={{ position: 'absolute', inset: 0, transform: `scale(${zoom})`, transformOrigin: '50% 50%', pointerEvents: 'none' }}>
      <video src={CARD_IMG} autoPlay loop muted playsInline style={{
        position: 'absolute', left: g.lx + 'px', top: (g.cardT + g.lift) + 'px',
        width: CARD_W + 'px', height: CARD_H + 'px', objectFit: 'cover',
        transform: `rotate(${g.tilt.toFixed(2)}deg)`,
        transformOrigin: `${(CARD_W / 2).toFixed(1)}px ${CARD_H}px`,
      }} />
    </div>
  );
}

function CardWheel({ cx, cy, a, ink }) {
  const spokes = [];
  for (let i = 0; i < 8; i++) {
    const ang = (i / 8) * Math.PI * 2;
    spokes.push(<line key={i} x1={cx} y1={cy}
      x2={cx + Math.cos(ang) * (CARD_RW - 9)} y2={cy + Math.sin(ang) * (CARD_RW - 9)}
      stroke="#9A9385" strokeWidth="2.5" />);
  }
  return (
    <g>
      <circle cx={cx} cy={cy} r={CARD_RW - 3} fill="none" stroke={ink} strokeWidth="7" />
      <g transform={`rotate(${a} ${cx} ${cy})`}>
        {spokes}
        <circle cx={cx + CARD_RW - 16} cy={cy} r="4" fill={ACCENTS[7]} />
        <circle cx={cx - CARD_RW + 16} cy={cy} r="4" fill={ACCENTS[5]} />
        <circle cx={cx} cy={cy} r="7" fill={ink} />
      </g>
    </g>
  );
}

function TowedCard({ T, X, bob, ink, wa }) {
  const g = cardGeo(T, X);
  const rx = g.rx, lx = g.lx, axleY = g.axleY, cardB = g.cardB, cardT = g.cardT;
  const tilt = g.tilt, lift = g.lift;
  // tow line: captain's seat cluster back to the card's top right corner
  const ax = X + 665, ay = 561 + bob;
  const tx = rx - 18, ty = cardT + 10 + lift;
  const glint = [];
  for (let i = 0; i < 22; i++) {
    const u = (i + 0.5) / 22;
    const gx = ax + (tx - ax) * u, gy = ay + (ty - ay) * u - Math.sin(Math.PI * u) * 16;
    const tw = 0.15 + 0.85 * Math.pow(0.5 + 0.5 * Math.sin(T * 5 + i * 1.9), 2);
    const r = 2 + 2.4 * tw;
    glint.push(<path key={i} transform={`translate(${gx.toFixed(1)} ${gy.toFixed(1)})`}
      d={`M0,${-r} L${r * 0.3},${-r * 0.3} L${r},0 L${r * 0.3},${r * 0.3} L0,${r} L${-r * 0.3},${r * 0.3} L${-r},0 L${-r * 0.3},${-r * 0.3} Z`}
      fill={i % 3 === 0 ? '#FFE9A8' : '#FFFFFF'} opacity={tw} />);
  }
  return (
    <g>
      <path d={`M${ax},${ay} Q${(ax + tx) / 2},${(ay + ty) / 2 - 16} ${tx},${ty}`}
        fill="none" stroke="#FFD9EA" strokeWidth="2.4" opacity="0.95" />
      {glint}
      <g transform={`translate(0 ${lift.toFixed(2)})`}>
        <line x1={lx + 52} y1={axleY} x2={rx - 52} y2={axleY} stroke={ink} strokeWidth="9" strokeLinecap="round" />
        <g transform={`rotate(${tilt.toFixed(2)} ${((lx + rx) / 2).toFixed(1)} ${cardB})`}>
          <rect x={lx - 9} y={cardT - 9} width={CARD_W + 18} height={CARD_H + 18} rx="10"
            fill="none" stroke={ink} strokeWidth="7" />
          <line x1={lx + 52} y1={cardB + 6} x2={lx + 52} y2={axleY} stroke={ink} strokeWidth="7" strokeLinecap="round" />
          <line x1={rx - 52} y1={cardB + 6} x2={rx - 52} y2={axleY} stroke={ink} strokeWidth="7" strokeLinecap="round" />
        </g>
        <CardWheel cx={lx + 52} cy={axleY} a={wa} ink={ink} />
        <CardWheel cx={rx - 52} cy={axleY} a={wa} ink={ink} />
      </g>
    </g>
  );
}

function Tandem({ ink, confetti }) {
  const { T, CUES, authoredTotal } = useComposition();
  const total = authoredTotal || 30;
  const t1 = CUES['Cruise'], t2 = CUES['Roll out'];
  const k = T / total;

  // where the bike sits on screen
  let X;
  if (T < t1) {
    const u = Math.max(0, T / t1);
    X = X_IN + (CRUISE_X - X_IN) * ((1 - Math.cos(Math.PI * u)) / 2);
  } else if (T < t2) {
    X = CRUISE_X;
  } else {
    const u = Math.min(1, (T - t2) / (total - t2));
    X = CRUISE_X + (X_OUT - CRUISE_X) * u * u;
  }

  // camera pans the world at a steady rate; the bike's true travel adds its
  // own screen motion, so the wheels always match the ground under them
  const dist = SCROLL * k;
  const travel = dist + X;
  const wheelA = (travel / (R * SCALE)) * (180 / Math.PI);
  const crankA = wheelA / 3 - 90;
  const chainOff = (travel / SCALE) * (CR / (3 * R));
  const bob = Math.sin(travel / (R * SCALE)) * 2.6;
  const zoom = 1 + 0.02 * (1 - Math.cos(2 * Math.PI * k)) / 2;

  const cr = crankA * Math.PI / 180;
  const cos = Math.cos(cr) * ARM, sin = Math.sin(cr) * ARM;
  const n1 = { x: B1.x + cos, y: B1.y + sin }, f1 = { x: B1.x - cos, y: B1.y - sin };
  const n2 = { x: B2.x + cos, y: B2.y + sin }, f2 = { x: B2.x - cos, y: B2.y - sin };

  return (
    <div style={{ width: W + 'px', height: H + 'px', background: SKY, position: 'relative', overflow: 'hidden' }}
      data-screen-label={`t=${T.toFixed(0)}s`}>
      <div style={{ position: 'absolute', inset: 0, transform: `scale(${zoom})`, transformOrigin: '50% 50%' }}>
        <Ground dist={dist} />
      </div>
      <CardArt T={T} X={X} zoom={zoom} />
      <svg style={{ position: 'absolute', inset: 0 }} width={W} height={H} viewBox={`0 0 ${W} ${H}`}>
        <g transform={`translate(${W / 2} ${H / 2}) scale(${zoom}) translate(${-W / 2} ${-H / 2})`}>
          <SkyBanner T={T} total={total} X={X} ink={ink} />
          <TowedCard T={T} X={X} bob={bob} ink={ink} wa={(travel / CARD_RW) * (180 / Math.PI)} />
        <g transform={`translate(${X} ${bob}) translate(${PIVOT_X} ${GROUND}) scale(${SCALE}) translate(${-PIVOT_X} ${-GROUND})`}>
            {confetti === false ? null : <Confetti T={T} total={total} />}

            <g fill="none" stroke={ink} strokeWidth="14" strokeLinecap="round">
              {TUBES.map((t, i) => <line key={i} x1={t[0]} y1={t[1]} x2={t[2]} y2={t[3]} />)}
              <line x1={HT.x} y1={HT.y} x2={HB.x} y2={HB.y} strokeWidth="17" />
              <path d={`M${HB.x},${HB.y} C1238,516 1252,570 ${FX},${WY}`} />
              <path d={`M${HT.x},${HT.y} L1214,350`} strokeWidth="11" />
              <path d="M1214,352 C1222,330 1248,320 1264,331 C1278,341 1272,367 1256,371" strokeWidth="11" />
              {/* stoker bars off the captain's seat tube */}
              <path d="M922,386 L874,354" strokeWidth="10" />
              <path d="M874,354 C860,346 850,350 850,362" strokeWidth="10" />
            </g>
            {confetti === false ? null : <Speckles />}
            <Saddle at={S1} color={ACCENTS[5]} ink={ink} />
            <Saddle at={S2} color={ACCENTS[0]} ink={ink} />

            <Wheel cx={RX} cy={WY} angle={wheelA} ink={ink} seed={0} />
            <Wheel cx={FX} cy={WY} angle={wheelA} ink={ink} seed={2} />

            <Chains off={chainOff} />
            <circle cx={RX} cy={WY} r={COG - 7} fill={CREAM} stroke={ink} strokeWidth="5" />
            <circle cx={RX} cy={WY} r={7} fill={ink} />

            <Pedal bb={B1} p={f1} shade="#5A5347" cap="#8E8677" />
            <Pedal bb={B2} p={f2} shade="#5A5347" cap="#8E8677" />
            <Chainring bb={B1} angle={crankA} ink={ink} />
            <Chainring bb={B2} angle={crankA} ink={ink} />
            <Pedal bb={B1} p={n1} shade={ink} cap={ACCENTS[3]} />
            <Pedal bb={B2} p={n2} shade={ink} cap={ACCENTS[6]} />

            <Rider hip={{ x: 570, y: 380 }} sh={{ x: 676, y: 202 }} head={{ x: 686, y: 110 }}
              grip={{ x: 854, y: 358 }} near={n1} far={f1} ink={ink}
              img={HEAD_AIS} iw={210} ih={446} ox={-110} oy={-326} />
            <Rider hip={{ x: 930, y: 380 }} sh={{ x: 1036, y: 202 }} head={{ x: 1086, y: 110 }}
              grip={{ x: 1248, y: 366 }} near={n2} far={f2} ink={ink}
              img={HEAD_SAZ} iw={218} ih={436} ox={-108} oy={-314} />
          </g>
        </g>
      </svg>
    </div>
  );
}

function TandemVideo(props) {
  const ink = props.ink || INK_DEFAULT;
  return React.createElement(
    CompositionStage,
    { width: W, height: H, scenes: window.OM_SCENES, playback: window.OM_PLAYBACK, bg: SKY },
    React.createElement(Tandem, { ink, confetti: props.confetti })
  );
}

window.TandemVideo = TandemVideo;
